def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    prev_bids = []
    strong_prev = 0.0
    needy_opponents = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            if opp.get('no_water_days', 0) >= 1 or opp.get('hp', 10) <= 4:
                needy_opponents += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                bid = prev.get('bid', 0.0)
                prev_bids.append(bid)
                if bid > strong_prev:
                    strong_prev = bid

    slots = int(supply // WATER_REQ)
    if slots < 0:
        slots = 0

    if budget <= 0:
        return 0.0

    if not alive:
        return float(min(budget, 18.0))

    high_pressure = strong_prev >= 120.0
    medium_pressure = strong_prev >= 90.0

    if hp <= 2 or no_water_days >= 2:
        target = max(110.0, strong_prev + 3.0)
        return float(min(budget, target))

    if slots >= 2:
        if hp >= 7 and no_water_days == 0:
            base = 22.0
            if medium_pressure:
                base = 34.0
            if day >= 8:
                base += 8.0
            return float(min(budget, base))
        else:
            base = 48.0
            if high_pressure:
                base = max(base, strong_prev * 0.55)
            return float(min(budget, base))

    base = 62.0
    if no_water_days >= 1:
        base = 88.0
    if hp <= 4:
        base = max(base, 96.0)
    if needy_opponents >= 2:
        base += 10.0
    if medium_pressure:
        base = max(base, min(strong_prev + 2.0, 118.0))
    if high_pressure and hp >= 6 and no_water_days == 0:
        base = min(base, 72.0)
    if day >= 9 and hp <= 5:
        base = max(base, 105.0)

    return float(min(budget, base))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    hp = float(my_status.get('hp', 0.0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append((oid, o))

    if not alive_opps:
        return max(0.0, min(budget, DAILY_SALARY * 0.4))

    # Read only yesterday's immediate trace bids
    prev_bids = []
    prev_by_opp = {}
    for oid, o in alive_opps:
        prev = o.get('previous_trace', {}) or {}
        bid = prev.get('bid', None)
        if bid is not None:
            try:
                bidf = float(bid)
                prev_bids.append(bidf)
                prev_by_opp[oid] = bidf
            except Exception:
                pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0

    # Estimate likely contention level from highest previous bid.
    # If someone bid near/above ~0.85*salary, assume strong pressure.
    pressure = 0.0
    if highest_prev_bid >= 0.85 * DAILY_SALARY:
        pressure = 1.0
    elif highest_prev_bid >= 0.6 * DAILY_SALARY:
        pressure = 0.7
    elif highest_prev_bid >= 0.4 * DAILY_SALARY:
        pressure = 0.4
    else:
        pressure = 0.2

    # Supply-based urgency: lower supply increases chance we lose water.
    supply_norm = 0.0
    if MAX_SUPPLY > MIN_SUPPLY:
        supply_norm = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
    supply_norm = max(0.0, min(1.0, supply_norm))
    scarcity = 1.0 - supply_norm

    # If we're already in danger (low hp or many no-water days), bid more.
    danger = 0.0
    if hp <= 2.0:
        danger = 1.0
    elif hp <= 4.0:
        danger = 0.7
    elif no_water_days >= 2:
        danger = 0.6
    else:
        danger = 0.3

    # Base bid: aim to beat aggressive bids only when pressure is high.
    # Use a small increment over the observed highest previous bid when pressured.
    if pressure >= 0.9:
        target = min(budget, highest_prev_bid + 3.0)
    elif pressure >= 0.6:
        target = min(budget, max(highest_prev_bid * 0.85, 0.55 * DAILY_SALARY) + 2.0)
    else:
        target = min(budget, (0.45 + 0.2 * scarcity + 0.2 * danger) * DAILY_SALARY)

    # Safety caps: never spend more than a fraction when hp is comfortable.
    if hp >= 6.0 and danger < 0.6:
        target = min(target, 0.55 * DAILY_SALARY)
    elif hp >= 4.0 and danger < 0.8:
        target = min(target, 0.75 * DAILY_SALARY)

    # If danger is high, allow spending up to ~salary.
    if danger >= 0.8:
        target = min(budget, max(target, 0.85 * DAILY_SALARY))

    # Ensure non-negative and not exceeding budget.
    if target < 0.0:
        target = 0.0
    if target > budget:
        target = budget

    return float(target)
